            "mode": "query"
          }
        },
        "0435a1709c314a789af0f957244f4e2e": {
          "id": "0435a1709c314a789af0f957244f4e2e",
          "stepType": "TextOutput",
          "name": "Limit  Reached",
          "secure": false,
          "value": [
            {
              "value": "(function execute() {\n    /* Return a quoted string.  For example:\n\n       if (vaInputs.first_name == 'Bill') {\n           return gs.getMessageLang(\"hi there {0}\", vaContext.getRequesterLang(), [vaInputs.first_name]);\n       } else {\n           return gs.getMessageLang(\"how are you {0}\", vaContext.getRequesterLang(), [vaInputs.last_name]);\n       }\n    */\n   if (vaSystem.isLiveAgentAvailable()){\n          return 'You have reached your NeedIt search limit. I will transfer you to a live agent for assistance.'\n      } else {\n          return 'You have reached your NeedIt search limit. If you need to work with multiple NeedIt records, open NeedIt > My NeedIt Requests.'\n      }\n})()\n",
              "mode": "script"
            }
          ],
          "isCollapsible": true,
          "requestFeedback": true,
          "applicability": {
            "value": "",
            "mode": "query"
          }
        },
        "0b0950c7c9c44c1199af72986b08c085": {
          "id": "0b0950c7c9c44c1199af72986b08c085",
          "name": "Transfer to Agent",
          "script": "(function execute() {\n    /* Code your scripted action here. For example, you might update a\n       record based on conditional logic:\n\n        if (vaVars.my_flag == 'say hello') {\n            gs.info('hi there');\n        } else {\n            gs.info('bye now');\n        }\n    */\n     vaSystem.connectToAgent()\n})()\n",
          "stepType": "ScriptAction",
          "applicability": {
            "mode": "script",
            "value": "(function execute() {\n    /* Return true or false to indicate if the topic or topic node can run\n       and be discoverable (or not).  For example:\n\n       var applicability = vaInputs.first_name == 'Bill' ? true : false;\n       return applicability;\n    */\n    if (vaSystem.isLiveAgentAvailable()){\n          return true;\n      } else {\n          return false;\n      }\n})()\n"
          }
        }
